"Also: wrecks of destroyed enemies, first-expedition depots and crystals (shoot them) give one-off ore.":"أيضًا: حطام الأعداء المدمَّرين ومخازن البعثة الأولى والبلّورات (حطّمها) تعطي خامًا لمرة واحدة.",
" Battle scale: income ×{0}.":" مقياس المعارك: الدخل ×{0}.",
