"New ore look: veins are glowing emerald faceted crystals on black basalt with sparks and green haze; the extractor is a hex pedestal with a honeycomb dome and a lattice tower topped by a green beacon (stripe and pennant in team colour)":"مظهر جديد للخام: العروق بلّورات زمردية مصقولة متوهجة على بازلت أسود مع شرارات وضباب أخضر؛ المستخرِج قاعدة سداسية بقبة خلوية وبرج شبكي يعلوه منارة خضراء (الشريط والراية بلون الفريق)",
"New in v6.1":"الجديد في v6.1",
"Preferred class like in Battlefield (U, numbers after death): you respawn into it when available":"فئتك المفضلة كما في Battlefield (U، أرقام بعد الموت): تظهر فيها عند توفّرها",
"Vehicles in first person (V — outside/cockpit); gentle aim assist — in Settings":"المركبات من منظور الشخص الأول (V — خارج/من المقصورة)؛ مساعدة تصويب خفيفة — في الإعدادات",
"Easy exit from the core: Space — to the shaft, B — capsule to the surface; ability effects reset on death":"الخروج من النواة أصبح سهلًا: Space — إلى العمود، B — كبسولة إلى السطح؛ تُعاد تأثيرات القدرات إلى الصفر عند الموت",
"Endless progression: generals and Marshal ★, career levels, weapon mastery and attachments, medals, daily contracts — Career screen":"تطوّر بلا نهاية: الجنرالات والمارشال ★، مستويات المسيرة، إتقان الأسلحة والملحقات، الأوسمة، العقود اليومية — شاشة \"المسيرة\"",
"Strategy: smooth wheel zoom, unit icons and labels (Alt — all), Troops / Buildings panel on the left":"الاستراتيجية: تكبير سلس بالعجلة، أيقونات وتسميات فوق الوحدات (Alt — الكل)، لوحة «القوات / المباني» على اليسار",
"RMB — attack-move, double RMB — march firing on the move; rare orders in \"More orders ▾\"; no duplicate buttons":"‏RMB — تقدّم وقاتل في الطريق، نقرتان بـ RMB — زحف مع إطلاق النار أثناء الحركة؛ الأوامر النادرة في «أوامر أخرى ▾»؛ لا أزرار مكرّرة",
"New in v6":"الجديد في v6",
"Shooter-grade guns: hitscan bullets, 720 RPM rifle, MG, recoil, RMB aim, magazines and R reload, hit markers":"أسلحة بمستوى ألعاب الرماية: رصاص فوري، بندقية 720 طلقة/د، رشّاش، ارتداد، تصويب بزر الفأرة الأيمن، مخازن وإعادة تعبئة بـ R، علامات إصابة",
"Heavier gravity, responsive jetpack, dash on Z or double jet in the air; the weapon no longer flies along when switching units":"جاذبية أثقل، حقيبة نفّاثة أكثر استجابة، اندفاع بـ Z أو نقرتان على الحقيبة في الجو؛ السلاح لم يعد يطير معك عند تبديل الوحدة",
"Builders: select a builder, pick a building, place a blueprint; extractors on ore veins; click \"ORE\" to see income and how to boost it":"المهندسون: حدّد مهندسًا، اختر مبنى، ضع المخطط؛ مستخرِجات على عروق الخام؛ انقر «الخام» لترى الدخل وكيف تزيده",
"Grey buttons explain why and offer a fix; bigger buttons, \"In progress\" strip, \"▶ Possess\", Tab is the one mode key":"الأزرار الرمادية قابلة للنقر — نعرض السبب وزر الحل؛ أزرار أكبر، شريط «قيد التنفيذ»، «▶ تحكّم»، Tab مفتاح واحد للأوضاع",
"Strategy camera without jumps or flips, zoom to cursor, draggable minimap":"كاميرا الاستراتيجية بلا قفزات أو انقلابات، تكبير نحو المؤشر، يمكن سحب الخريطة المصغّرة",
"New vehicles: Jackal raider, Grad MLRS (homing rockets), Hammer mortar; the Swarm gets Wasp, Hive, Trebuchet":"آليات جديدة: المغير «ابن آوى»، «غراد» (صواريخ موجّهة)، الهاون «المطرقة»؛ ولدى النحل «الدبّور» و«الخلية» و«المنجنيق»",
"The strategist keeps orders and stops voice spam; fights come to you; B — redeploy, Shift+B — into the fight; compass, H — which target":"الاستراتيجي لا يغيّر الأوامر ولا يزعجك بالصوت؛ المعارك تأتيك؛ B — إعادة نشر، Shift+B — إلى قلب المعركة؛ بوصلة، H — أي هدف",
"Free play (K) and going solo (J), F2 presets; Esc pauses and resumes; saves: slots, export and import":"حرية التصرف (K) و«أتصرف وحدي» (J)، F2 — إعدادات مسبقة؛ Esc — إيقاف مؤقت واستئناف؛ الحفظ: خانات، تصدير واستيراد ملف",
"New in v5.3":"الجديد في v5.3",
"Flight: stronger gravity far from the meteor, C in the air brakes, thrust steers sharper; no more getting stuck in the portal":"الطيران: جاذبية أقوى بعيدًا عن النيزك، C في الجو — فرامل، الدفع يوجّه بحدّة أكبر؛ لن تعلق في البوابة بعد الآن",
"New in v5":"الجديد في v5",
"Endless war by default and battle scale: normal, large, epic":"معركة لا تنتهي افتراضيًا ومقياس المعارك: عادي، كبير، ملحمي",
"Save and load the battle (autosave every 3 minutes)":"حفظ المعركة وتحميلها (وحفظ تلقائي كل 3 دقائق)",
"Squadmates with callsigns: portraits, health and live chatter":"الفرقة بأسماء نداء: صور شخصية، صحة، وأحاديث حيّة",
"Fog of war in strategy, friends and foes outlined differently":"ضباب الحرب في الاستراتيجية، والأصدقاء والأعداء بتمييز مختلف",
"Camera fly-over when switching, portal aurora instead of rings":"تحليق الكاميرا عند التبديل، شفق البوابة بدل الحلقات",
"Side tasks, sky shortcut, first-expedition habitats with supplies, crystals, crater ice, dust storms":"مهام جانبية، اختصار عبر السماء، وحدات سكنية للبعثة الأولى بمؤن، بلّورات، جليد في الفوّهات، عواصف غبار",
