"Grenade: hold G to see the arc and blast circle; drag on the button to aim; release to throw.":"القنبلة: اضغط مطوّلًا G — ترى المسار ودائرة الانفجار؛ حرّك إصبعك على الزر — الزاوية؛ أفلِت — رمي.",
"Grenade: hold {0} for the arc and blast circle, release to throw. Range — by view angle, wheel — power, RMB — underhand.":"القنبلة: اضغط مطوّلًا {0} للمسار ودائرة الانفجار، أفلِت للرمي. المدى — بزاوية النظر، العجلة — القوة، زر الفأرة الأيمن — رمية من الأسفل.",
"Grenades: hold G for the flight arc, blast point and radius, distance; release to throw. Range by view angle, wheel — power, RMB — underhand":"القنابل: اضغط مطوّلًا G لمسار الطيران ونقطة الانفجار ونصف القطر والمسافة؛ أفلِت للرمي. المدى بزاوية النظر، العجلة — القوة، زر الفأرة الأيمن — رمية من الأسفل",
"Grenades bounce and roll down slopes, 2.5 s fuse; 2 grenades, 9 s recharge; warning icon for enemy grenades nearby":"القنبلة ترتدّ وتتدحرج على المنحدرات، فتيل 2.5 ث؛ قنبلتان، إعادة الشحن 9 ث؛ أيقونة تحذير من قنبلة معادية قريبة",
"Grenade: hold — arc and blast point, release — throw · tank overdrive":"القنبلة: اضغط مطوّلًا — المسار ونقطة الانفجار، أفلِت — رمي · تعزيز الدبابة",
"G — hold: see the arc and blast circle, release to throw. 2.5 s fuse, 2 grenades.":"‏G — اضغط مطوّلًا: يظهر المسار ودائرة الانفجار، أفلِت للرمي. الانفجار بعد 2.5 ث، قنبلتان.",
"Grenade ({0}): hold — flight arc, blast point and radius, distance; release — throw; a quick tap throws at once. Range by view angle, wheel — power, RMB — underhand. Phone: hold G and drag.":"القنبلة ({0}): اضغط مطوّلًا — مسار الطيران ونقطة الانفجار ونصف القطر والمسافة؛ أفلِت — رمي؛ نقرة سريعة ترمي فورًا. المدى بزاوية النظر، العجلة — القوة، زر الفأرة الأيمن — رمية من الأسفل. الهاتف: اضغط مطوّلًا G وحرّك إصبعك.",
