"Each level costs more than the last; every 50 levels — \"Veteran ★\". XP comes from everything: combat, orders, medals, contracts.":"كل مستوى أغلى من السابق؛ وكل 50 مستوى — «محارب قديم ★». الخبرة تأتي من كل شيء: القتال، الأوامر، الأوسمة، العقود.",
