"Possess vehicles and drones":"التحكّم بالآليات والطائرات المسيّرة",
"On the gun: {0}. The AI drives, you shoot. {1} — get off":"على المدفع: {0}. الذكاء الاصطناعي يقود وأنت تطلق النار. {1} — انزل",
