"{0} — man the gun: {1}":"‏{0} — تولَّ المدفع: {1}",
"Combo ×{0} · reflex +{1}%":"كومبو ×{0} · ردّ فعل +{1}%",
"Strategist: troopers dropping to you — +{0} (−{1} ore)":"الاستراتيجي: إنزال جنود إليك — +{0} (−{1} خام)",
"Hold on, sending troopers your way":"اصمد، سأرسل إليك جنودًا",
"· basic{0}":"‏· أساسية{0}",
"· advanced":"‏· متقدّمة",
"· rare":"‏· نادرة",
"Advanced: class order":"متقدّم: ترتيب الفئات",
"Voice of hints and curator":"صوت التلميحات والمرشد",
"Advanced: custom class order":"متقدّم: ترتيب فئات مخصّص",
"Voice of hints & curator":"صوت التلميحات والمرشد",
"Phone: three stick modes. Left only — \"auto\" (strong magnet, weaker bullets). Right only — aiming turns on by itself, stronger magnet, better accuracy. Both — no aiming, weaker magnet and accuracy. The 👁 button on the right hides/returns the HUD.":"الهاتف: ثلاثة أوضاع للعصي. اليسرى فقط — «تلقائي» (مغناطيس قوي، رصاص أضعف). اليمنى فقط — يعمل التصويب تلقائيًا، مغناطيس أقوى ودقة أفضل. كلتاهما — بلا تصويب، مغناطيس ودقة أقل. زر 👁 يمينًا يُخفي الواجهة أو يعيدها.",
"Phone: strategy simplified — engineer and buildings only. Cards on the left (engineer, HQ, barracks…): tap — the camera flies there, the bottom bar shows what to build/produce. \"To battle\" — top left. The army fights by itself. Full strategy — Settings → Phone.":"الهاتف: استراتيجية مبسّطة — المهندس والمباني فقط. بطاقات يسارًا (مهندس، مقر، ثكنة…): انقر — تطير الكاميرا إليه، ويعرض الشريط السفلي ما تبنيه/تنتجه. «إلى المعركة» — أعلى اليسار. يقاتل الجيش بنفسه. الاستراتيجية الكاملة — الإعدادات ← الهاتف.",
"Possession — two switches: \"Squads\" and \"Vehicles\" (vehicles are off by default on phones — the AI drives them). With vehicles off, E (phone: the button on the right) next to a friendly vehicle — man its gun: it drives itself, you shoot. The old custom class order is under \"Advanced\". A unit answers on the radio when you possess it.":"التحكّم — مفتاحان: «الفرق» و«الآليات» (الآليات معطّلة افتراضيًا على الهاتف — يقودها الذكاء الاصطناعي). إن كانت الآليات معطّلة، فاضغط E (على الهاتف: الزر يمينًا) بجانب آلية صديقة — لتتولى مدفعها: تقود نفسها وأنت تطلق النار. ترتيب الفئات المخصّص القديم تحت «متقدّم». تردّ الوحدة على اللاسلكي عند التحكّم بها.",
"Smart hints: basic hints switch off after the 2nd launch, but the game still points out a feature you never use. Switches: basic / advanced / rare, and a separate one for the voice of hints and curator.":"تلميحات ذكية: تنطفئ الأساسية تلقائيًا بعد التشغيل الثاني، لكن اللعبة تنبّهك إلى ميزة لا تستخدمها. المفاتيح: أساسية / متقدّمة / نادرة، ومفتاح منفصل لصوت التلميحات والمرشد.",
"Reflex charges from kills (streaks charge more). Squadmates fell behind or died — the strategist drops new ones to you (pricier than normal reinforcement). The v7.2gfx graphics and sound are merged in: billowing explosions, smoke, debris, shaft and crater acoustics. The build date is real now.":"يُشحن ردّ الفعل من القتلى (السلسلة تشحن أكثر). تأخّر زملاؤك في الفرقة أو سقطوا — ينزل الاستراتيجي بدلاء لهم إليك (أغلى من التعزيز العادي). دُمجت رسومات v7.2gfx وصوتها: انفجارات متصاعدة، دخان، حطام، وصوتيات الأنفاق والفوّهات. تاريخ الإصدار حقيقي الآن.",
