"Career and saves stay untouched. In battle the same menu is the \"🛠 Menu\" button at the top right{0}.":"لا تتغيّر المسيرة ولا الحفظ. في المعركة هذه القائمة نفسها هي زر «🛠 القائمة» أعلى اليمين{0}.",
