"Cinema: everything built":"سينما: كل شيء مبني",
"both bases built and upgraded — for footage":"القاعدتان مبنيتان ومطوَّرتان — للتصوير",
"Cinema mode — split screen: the strategist bot on the left (top view of the base and army), the shooter bot on the right in first person. Buttons at the bottom (keys S, P): \"Split screen\" and \"★ All built\" — both bases built and upgraded for footage.":"وضع السينما — شاشة منقسمة: روبوت الاستراتيجي يسارًا (منظر علوي للقاعدة والجيش)، وروبوت الرامي يمينًا من منظور الشخص الأول. أزرار في الأسفل (والمفتاحان S وP): «شاشة منقسمة» و«★ كل شيء مبني» — القاعدتان مبنيتان ومطوَّرتان للتصوير.",
"The core and the tunnels through the meteor are gone — the meteor is solid, the fight is on the surface only.":"لم تعد هناك نواة ولا أنفاق عبر النيزك — النيزك صلب، والقتال على السطح فقط.",
"Phone: 👁 hides the HUD but keeps the jetpack, ⇆, the sticks and the objective marker. \"◎ Aim\" (right finger only) — a clearly stronger and wider magnet; the magnet for all three modes — Settings → Controls → \"Advanced\". On a vehicle gun the button says \"Get off\".":"الهاتف: 👁 يخفي الواجهة لكنه يُبقي الحقيبة النفّاثة وزر ⇆ والعصيّين وعلامة المهمة. «◎ تصويب» (بالإصبع الأيمن فقط) — مغناطيس أقوى وأوسع بوضوح؛ قوة المغناطيس للأوضاع الثلاثة — الإعدادات ← التحكم ← «متقدّمة». عند مدفع المركبة يصبح اسم الزر «انزل».",
"Training: phones show phone trainings only, PCs — PC only. All 4 are in the \"🛠 Developer\" menu. Developer mode and the Arsenal are one menu now (in battle — \"🛠 Menu\" at the top right, F8 on PC).":"التدريب: على الهاتف تظهر تدريبات الهاتف فقط، وعلى الحاسوب — تدريبات الحاسوب فقط. الأربعة كلها في قائمة «🛠 المطوّر». وضع المطوّر والترسانة أصبحا قائمة واحدة (في المعركة — «🛠 القائمة» أعلى اليمين، وعلى الحاسوب F8).",
"Graphics styles \"Dendy (8-bit)\" and \"16-bit\": Settings → Graphics → \"Graphics style\" (details — the ⚙ button). If FPS is below 24 in the first ~10 s of a match, Dendy turns on by itself (still below 20 — bigger pixels, 120 lines); the \"back to normal\" notice restores normal graphics for good. Your own choice in the menu always wins.":"نمطا الرسومات «Dendy (8 بت)» و«16 بت»: الإعدادات ← الرسومات ← «نمط الرسومات» (التفاصيل — زر ⚙). إذا كان FPS أقل من 24 في أول ~10 ث من المباراة، يعمل Dendy تلقائيًا (وإن بقي أقل من 20 — بكسلات أكبر، 120 سطرًا)؛ إشعار «العودة للعادي» يعيد الرسومات العادية نهائيًا. اختيارك في القائمة هو الأهم دائمًا.",
"3D environment models (ruins, wrecks, fortifications) — only well-rated ones, streamed on demand. Turn off: Settings → Graphics → \"New 3D environment models\".":"نماذج ثلاثية الأبعاد للبيئة (أطلال، حطام، تحصينات) — فقط ذات التقييمات الجيدة، وتُحمَّل عند الطلب. للإيقاف: الإعدادات ← الرسومات ← «نماذج بيئة ثلاثية الأبعاد جديدة».",
