"Troopers can build: E (phone: \"Enter\") at a friendly construction site — your trooper builds it, squadmates nearby help. If the engineers are busy, the strategist asks you for help — a \"BUILD SITE\" marker.":"البناء بالجنود: E (على الهاتف «دخول») عند موقع بناء حليف — جندك يبني بنفسه، وزملاؤك القريبون يساعدون. إذا كان المهندسون مشغولين، يطلب منك الاستراتيجي المساعدة بنفسه — علامة «موقع بناء».",
"Strategist marks: the strategist puts ⌖ on an enemy cluster near you — artillery hits it 8 s later and nearby friendly \"Grad\" MLRS fire a salvo. Your own artillery strike from strategy mode gets \"Grad\" support too.":"علامات الاستراتيجي: يضع الاستراتيجي ⌖ على تجمّع أعداء قربك — يصيبه القصف المدفعي بعد 8 ث، وتطلق منظومات \"غراد\" الحليفة القريبة رشقة. ضربتك المدفعية من وضع الاستراتيجية تحظى بدعم \"غراد\" أيضًا.",
"Weapon caches in cargo containers and crashed satellites (📦 visible within 70 m): E — a heavy MG for 90 s, incendiary rounds or rockets, plus full grenades. Crawling: Ctrl — go prone / stand up (lower, steadier aim, but slow).":"مخابئ الأسلحة في حاويات الشحن والأقمار الصناعية المتحطمة (📦 تُرى من 70 م): E — رشّاش ثقيل لمدة 90 ث، أو ذخيرة حارقة، أو صواريخ، مع قنابل يدوية ممتلئة. الزحف: Ctrl — انبطح / قف (أخفض وأهدأ وأدق تصويبًا، لكن ببطء).",
