"Three phone stick modes, simple strategy, vehicle gun seat, canyon terrain, squad classes, explosives":"ثلاثة أوضاع للعصيّين على الهاتف، استراتيجية مبسّطة، مقعد مدفع المركبة، تضاريس بأخاديد، فئات الفرق، متفجرات",
