"Link copied":"نُسخ الرابط",
"\"▶ Play now\" — the first menu button: a short flight under the portal sky and straight into battle (skip with any key or a tap).":"‏«▶ العب الآن» — أول زر في القائمة: تحليق قصير تحت سماء البوابة ثم مباشرة إلى المعركة (للتخطي — أي مفتاح أو نقرة).",
"Hits feel like hits: a metallic sound and sparks, a kill marker at the crosshair (headshot — yellow), a ×N streak, smooth shake from explosions, slow motion on key kills. Shake, slow motion and the hint can be turned off in Settings.":"الإصابات تُحَسّ: صوت معدني وشرارات، وعلامة إبادة عند المصوّبة (الرأس — صفراء)، وسلسلة ×N، واهتزاز سلس من الانفجارات، وحركة بطيئة عند الإبادات المهمة. يمكن إيقاف الاهتزاز والحركة البطيئة والتلميح من الإعدادات.",
"Match results: time, kills, best streak, ★ MVP and best squad, a match card — \"⇪ Share\", PNG or a link to the game.":"نتيجة المباراة: الوقت، الإبادات، أفضل سلسلة، ★ MVP وأفضل فرقة، وبطاقة المباراة — «⇪ مشاركة»، PNG أو رابط اللعبة.",
"A \"what to do now\" hint on the left under resources: the strategist's order, a point to capture, a Swarm attack. ✕ or F7 — collapse.":"تلميح «ماذا تفعل الآن» على اليسار تحت الموارد: أمر الاستراتيجي، أو نقطة للاستيلاء، أو هجوم السِّرب. ✕ أو F7 — طيّ.",
"The battle saves itself when you close or hide the tab — \"⟲ Continue\" in the menu.":"تُحفظ المعركة تلقائيًا إذا أغلقت التبويب أو أخفيته — «⟲ متابعة» في القائمة.",
"v7.5 stays in the \"🕘 Game version\" menu in case you prefer it. Anonymous statistics (no names or e-mail) are now sent; turn off in Settings.":"يبقى v7.5 في قائمة «🕘 إصدار اللعبة» إن فضّلته. تُرسَل الآن إحصاءات مجهولة (بلا أسماء أو بريد إلكتروني)؛ للإيقاف — في الإعدادات.",
"\"Play now\", hit feedback, match results with a share card, \"what to do\" hint, autosave":"‏«العب الآن»، ردّ فعل الإصابات، نتيجة المباراة مع بطاقة، تلميح «ماذا تفعل»، حفظ تلقائي",
"and older: v7.5, v7.4, milestones v1–v7.0":"والأقدم: v7.5، v7.4، المحطات v1–v7.0",
"New in v7.6":"الجديد في v7.6",
"NEW IN v7.6":"الجديد في v7.6",
"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"اختيار الفصيل قبل المباراة: «الاتحاد» (مشاة ثقيلة بدروع قوة، دروع ومدفعية) أو «السرب» (سرعة، أسراب طائرات مسيّرة، طلقات ثقيلة مع تشويه). يلعب الذكاء الاصطناعي بالفصيل الآخر. يُحفظ اختيارك.",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"لكل فصيل آلياته وحصرياته: للكونسورتيوم — دبابة «وحيد القرن» و«ألواح السيراميت»، وللسِّرب — «سرب الطائرات المسيّرة» و«حقائب نفّاثة طورية». تم فحص التوازن بمباريات البوتات.",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"فوّهات الانفجارات: القصف المدفعي والصواريخ ومدافع الدبابات تحفر حفرًا في النيزك — يمكنك المشي والقيادة عبرها والاحتماء داخلها.",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"منظور الشخص الثالث للجندي (V، يُحفظ اختيارك؛ على الهاتف — التحكم) وكاميرا سلسة للمركبات مع علامة تُظهر أين ستصيب القذيفة.",
"v7.6 stays in the \"🕘 Game version\" menu in case you prefer it.":"بقيت النسخة v7.6 في قائمة «🕘 إصدار اللعبة» إن فضّلتها.",
"Consortium / Swarm factions with a choice before the match, explosion craters, third-person view":"فصيلا الكونسورتيوم / السِّرب مع اختيار قبل المباراة، فوّهات الانفجارات، منظور الشخص الثالث",
