"Anomaly ahead! The vein is singing — go around!":"شذوذ أمامنا! العِرق يُغنّي — تجنّبوه!",
"Hear that hum? A singing vein. Keep clear!":"أتسمعون هذا الدويّ؟ عِرق مُغنٍّ. ابتعدوا!",
"Anomaly! The air is swirling — a whirlpool, go around!":"شذوذ! الهواء يلتف — إنها دوّامة، تجنّبها!",
"Rocks floating in the air… A whirlpool! Stay out!":"صخور معلّقة في الهواء… دوّامة! لا تقترب!",
"Anomaly ahead — it is crackling with current!":"شذوذ أمامنا — يطقطق بالتيار!",
"Rods and lightning — a Crackler. It loves armour!":"قضبان وبرق — طقطاق. يحب الدروع!",
"Anomaly! The ground shimmers with heat — a Brazier!":"شذوذ! الأرض ترتجف من الحرارة — مِجمرة!",
"Careful, a Brazier underfoot!":"احذر، مِجمرة تحت قدميك!",
"Anomaly — green mist! Acid, hold your breath!":"شذوذ — ضباب أخضر! حمض، احبسوا أنفاسكم!",
"The mist is drifting our way, go around!":"الضباب يزحف نحونا، تجنّبوه!",
"Anomaly! The air is like glass — a Lens, it bends bullets!":"شذوذ! الهواء كالزجاج — عدسة، تحني الرصاص!",
"Everything is warping… a Lens nearby!":"كل شيء يتشوّه… عدسة قريبة!",
"Ha! An enemy walked right into the anomaly!":"ها! عدو دخل في الشذوذ مباشرة!",
"Got him! Lure them into anomalies!":"أصبته! استدرجوهم إلى الشذوذات!",
"Beautiful zap! One less tin can.":"صعقة جميلة! علبة صفيح أقل.",
"The anomaly got me!":"أصابني الشذوذ!",
"Ow! Don't go in there!":"آه! لا تدخلوا هناك!",
"Discharged! It is dormant now.":"فرّغته! صار خاملًا الآن.",
"Clear, the anomaly is discharged.":"آمن، الشذوذ تفرّغ.",
"They say veins hide artifacts. Only first the vein sings…":"يقولون إن العروق تخبّئ قطعًا أثرية. لكن العِرق يُغنّي أولًا…",
"Throw a bolt first, then walk. Old habit.":"ارمِ مسمارًا أولًا، ثم امشِ. عادة قديمة.",
