" — close":" ‏— إغلاق",
"Supply drop":"إسقاط إمدادات",
"Drops a crate near your forces: ammo, grenades, rockets, weapon parts, a repair kit.":"يُسقط صندوقًا قرب قواتك: ذخيرة، قنابل يدوية، صواريخ، قطع أسلحة، عدّة إصلاح.",
"\"Grad\" rocket strike":"ضربة \"غراد\" الصاروخية",
"16 rockets over a wide area after 3 seconds — faster and wider than artillery.":"‏16 صاروخًا على مساحة واسعة بعد 3 ثوانٍ — أسرع وأوسع من القصف المدفعي.",
"Support: crate, recon, \"Grad\", artillery (then 1–4)":"الدعم: صندوق، استطلاع، \"غراد\"، قصف مدفعي (ثم 1–4)",
"WARNING: Swarm \"Grad\" incoming on your area!":"تحذير: «غراد» النحل يستهدف منطقتكم!",
"Warning! Rocket salvo on our position!":"تحذير! وابل صاروخي على موقعنا!",
"take the supply crate":"خذ صندوق الإمدادات",
"Anomalies on the meteor (wave 1): the \"Singing Vein\" — a glowing green crystal that hums and strikes everyone nearby with rhythmic pulses; the \"Whirlpool\" pulls and slams, the \"Crackler\" arcs between rods, the \"Brazier\" bursts into flame underfoot, the \"Acid mist\" and the \"Lens\" (bends bullets and your view) drift around.":"الشذوذات على النيزك (الموجة 1): «العِرق المُغنّي» — بلّورة خضراء متوهّجة تدوّي وتضرب كل من حولها بنبضات إيقاعية؛ «الدوّامة» تسحب وتقذف، و«الطقطاق» يطلق البرق بين القضبان، و«المِجمرة» تشتعل تحت قدميك، و«الضباب الحمضي» و«العدسة» (تحني الرصاص والصورة) تتجوّلان.",
"You can feel anomalies in advance (hum, glow, heat haze). Discharge one with a grenade, a rocket or a bolt (E near it): it goes dormant and sometimes leaves an artifact with a plus and a minus. Your squad warns over the radio, and enemies (and friends) sometimes blunder in — lure them!":"يمكنك الإحساس بالشذوذات مسبقًا (دويّ، توهّج، سراب حراري). فرّغ أحدها بقنبلة يدوية أو صاروخ أو مسمار (E عنده): سيخمد وقد يترك أثرًا فنيًا بميزة وعيب. تحذّرك فرقتك عبر اللاسلكي، وأحيانًا يقع الأعداء (والحلفاء) فيها — استدرجهم!",
"Support for command points: 4 in battle (📡 on the phone) — supply drop, recon scan, \"Grad\" rocket strike, artillery at the crosshair. The strategist sees anomalies on the map only after a scan.":"الدعم مقابل نقاط القيادة: 4 في المعركة (📡 على الهاتف) — إسقاط إمدادات، استطلاع، ضربة \"غراد\" الصاروخية، قصف مدفعي عند المؤشّر. يرى الاستراتيجي الشذوذات على الخريطة بعد المسح فقط.",
"Supply crates in ruins of old expeditions, near the HQs and next to finished buildings: ammo, grenades, rockets, weapon parts (they unlock attachments).":"صناديق الإمدادات في أطلال البعثات القديمة، قرب المقرّات وبجوار المباني المكتملة: ذخيرة، قنابل يدوية، صواريخ، قطع أسلحة (تفتح الملحقات).",
"v7.7 stays in the \"🕘 Game version\" menu. Anomalies can be turned off in Settings.":"بقيت النسخة v7.7 في قائمة «🕘 إصدار اللعبة». يمكن إيقاف الشذوذات من الإعدادات.",
"Anomalies (the \"Singing Vein\" and 5 more), discharge with a bolt or grenade, artifacts, support calls for CP, supply crates":"الشذوذات («العِرق المُغنّي» و5 أخرى)، التفريغ بالمسمار والقنبلة اليدوية، الآثار الفنية، استدعاء الدعم بنقاط القيادة، صناديق الإمدادات",
"and older: v7.7, v7.6, milestones v1–v7.0":"والنسخ الأقدم: v7.7، v7.6، محطات v1–v7.0",
"New in v7.8":"الجديد في v7.8",
"NEW IN v7.8":"الجديد في v7.8",
"Close":"إغلاق",
"Anomalies on the meteor":"الشذوذات على النيزك",
"☰ in the corner opens the pause menu: Resume, Restart, Training, Graphics, Settings, Main menu (with confirmation). Phone: ☰ at the top right (battle actions — the \"⚡ Actions\" tile); PC: the \"☰ Menu\" button at the top right or Esc.":"‏☰ في الزاوية يفتح قائمة الإيقاف المؤقت: متابعة، إعادة البدء، التدريب، الرسومات، الإعدادات، القائمة الرئيسية (مع تأكيد). الهاتف: ☰ أعلى اليمين (إجراءات المعركة — مربّع «⚡ الإجراءات»)؛ الحاسوب: زر «☰ القائمة» أعلى اليمين أو Esc.",
"Graphics are always normal by default — Dendy only if you pick it: the \"Graphics: Normal / Dendy (8-bit) / 16-bit\" switch is right in the main menu and the pause menu. If the game lags badly, a tip with a \"Turn on Dendy\" button appears.":"الرسومات عادية دائمًا افتراضيًا — Dendy فقط إن اخترتها: مفتاح «الرسومات: عادية / Dendy (8 بت) / 16 بت» في القائمة الرئيسية وقائمة الإيقاف المؤقت. إن كانت اللعبة تتباطأ كثيرًا يظهر تلميح مع زر «تشغيل Dendy».",
"Phone and tablet: the \"✋\" action button on the right appears only when there is something to do nearby — \"Take\" (cache, crate), \"Board\" (vehicle, turret, gun), \"Build\", \"Get off\", \"Bolt\" at an anomaly. You can also just tap the highlighted object.":"الهاتف واللوح: يظهر زر الإجراء «✋» على اليمين فقط عند وجود ما يمكن فعله قربك — «خذ» (مخبأ، صندوق)، «اركب» (مركبة، برج مدفعي، مدفع)، «ابنِ»، «انزل»، «مسمار» عند شذوذ. ويمكنك أيضًا نقر العنصر المضيء فقط.",
"Phone, strategy: hold a finger ~0.3 s (the phone buzzes, a yellow ring appears) and drag — a selection box; a normal swipe moves the camera. There is also the \"Box\" button on the right; in the training the \"Box\" step also accepts tapping a squad.":"الهاتف، الاستراتيجية: اضغط بإصبعك ~0.3 ث (يهتزّ الهاتف وتظهر حلقة صفراء) ثم اسحب — يظهر إطار تحديد؛ السحب العادي يحرّك الكاميرا. وهناك أيضًا زر «إطار» على اليمين؛ وفي التدريب تقبل خطوة «إطار» نقر فرقة أيضًا.",
"Phone: tiny buttons are easier to hit, the 📡 support list is bigger, strategy panels no longer cover the pause and results screens. v7.8 stays in the \"🕘 Game version\" menu.":"الهاتف: صار الضغط على الأزرار الصغيرة أسهل، وقائمة الدعم 📡 أكبر، ولم تعد لوحات الاستراتيجية تغطي شاشتي الإيقاف المؤقت والنتائج. بقيت النسخة v7.8 في قائمة «🕘 إصدار اللعبة».",
"☰ menu on phone and PC, no auto-Dendy, \"✋\" button on touch, box selection on phone":"قائمة ☰ على الهاتف والحاسوب، بدون Dendy تلقائي، زر «✋» على اللمس، تحديد بالإطار على الهاتف",
"16-bit":"‏16 بت",
"Lagging? Try the Dendy graphics — they are lighter.":"تتباطأ؟ جرّب رسومات Dendy — فهي أخف.",
"Turn on Dendy":"تشغيل Dendy",
"Use":"إجراء",
