"The current battle ends and a new match starts with the same settings.":"ستنتهي المعركة الحالية وتبدأ مباراة جديدة بالإعدادات نفسها.",
"Yes, restart":"نعم، من جديد",
"Yes, quit":"نعم، اخرج",
