"Restart":"إعادة البدء",
"Shooter":"الرامي",
"The Commander mode is not in the game yet":"وضع «القائد» غير متوفّر في اللعبة بعد",
"Commander · soon":"القائد · قريبًا",
"Commander — still in development":"القائد — قيد التطوير",
"Pause: resume, restart, training, graphics, settings, main menu":"الإيقاف المؤقت: متابعة، إعادة البدء، التدريب، الرسومات، الإعدادات، القائمة الرئيسية",
"Menu: pause, restart, training, graphics, settings":"القائمة: إيقاف مؤقت، إعادة البدء، التدريب، الرسومات، الإعدادات",
"Hold a finger on the ground ~0.3 s — the phone buzzes and a yellow ring appears — then drag without lifting: a box appears. Or use the \"Box\" button on the right. Simply tapping a squad also works.":"اضغط بإصبعك على الأرض ~0.3 ث — يهتزّ الهاتف وتظهر حلقة صفراء — ثم اسحب دون رفع الإصبع: يظهر إطار. أو استخدم زر «إطار» على اليمين. ويكفي أيضًا نقر فرقة.",
"Full screen on iPhone: \"Share\" ⬆ → \"Add to Home Screen\" — the game opens without the Safari bars.":"للشاشة الكاملة على iPhone: «مشاركة» ⬆ ← «إضافة إلى الشاشة الرئيسية» — تُفتح اللعبة دون أشرطة Safari.",
"Open portal-meteor.pages.dev for that.":"افتح لذلك الموقع portal-meteor.pages.dev.",
"Tap — select · tap ground — move · hold — command menu · hold and drag — box · 2 fingers — zoom":"نقرة — تحديد · نقرة على الأرض — تحرّك · اضغط مطوّلًا — قائمة الأوامر · اضغط مطوّلًا واسحب — إطار · إصبعان — تكبير",
"Robo-ninja":"روبو-نينجا",
"Assassin hero: blink-dashes, katana, shurikens. Teleports through enemy zones on her own and cuts robots apart. 1 per side.":"بطلة اغتيال: اندفاعات انتقالية، كاتانا، شوريكن. تنتقل بنفسها بين مناطق العدو وتقطّع الروبوتات. واحدة لكل جانب.",
"Shadow protocol":"بروتوكول «الظل»",
"Research: unlocks the robo-ninja in the Barracks. Requires a finished Mech factory.":"بحث: يفتح روبو-نينجا في الثكنة. يتطلب مصنع آليات مكتملًا.",
"Hero (1 per side): teleports through enemy zones on her own and cuts robots apart; possess her to play manually.":"بطلة (واحدة لكل جانب): تنتقل بنفسها بين مناطق العدو وتقطّع الروبوتات؛ استحوذ عليها للعب يدويًا.",
"is ready. She works on her own (AUTO) — possess her to play manually":"جاهزة. تعمل بنفسها (آلي) — استحوذ عليها للعب يدويًا",
"Robo-ninja ready for action":"روبو-نينجا جاهزة للمعركة",
"⚠ Intel: the enemy has a robo-ninja!":"‏⚠ استطلاع: ظهرت روبو-نينجا لدى العدو!",
"Warning! The enemy has a robo-ninja. Stay together":"تحذير! لدى العدو روبو-نينجا. ابقوا معًا",
"cyber blinks":"اندفاعات سيبرانية",
"Too far for a dash — get closer or teleport":"بعيد على الاندفاع — اقترب أو انتقل آنيًا",
"point ":"نقطة ",
"enemy group":"مجموعة العدو",
"order":"أمر",
"nearby":"قريب",
"Zone cleared":"تم تطهير المنطقة",
"⚔ NINJA DUEL! Block right before a hit to parry, blink to dodge. Watch for the wind-up flash":"‏⚔ مبارزة النينجا! احجب قبل الضربة مباشرة للصدّ، واندفع للمراوغة. راقب وميض التأهّب",
"The two ninjas have met in a duel!":"التقت النينجتان في مبارزة!",
"⚔ Duel won! Our ninja prevails":"‏⚔ تم الفوز بالمبارزة! نينجتنا تنتصر",
"⚔ Duel lost…":"‏⚔ خسرنا المبارزة…",
"ninja duel":"مبارزة النينجا",
"POSTURE BROKEN":"انكسر الثبات",
"Teleport":"انتقال آني",
"Teleport: aim at the ground (up to 150 m)":"انتقال آني: صوّب نحو الأرض (حتى 150 م)",
"✶ AUTO: she hops through enemy zones and cuts on her own. Stick / WASD pauses it for 1.5 s":"‏✶ آلي: تقفز بنفسها بين مناطق العدو وتقطّع. العصا / WASD توقفها 1.5 ث",
"✶ Manual: tap an enemy — dash & cut, swipe — slash, 🛡 — block":"‏✶ يدوي: انقر عدوًا — اندفاع وضربة، اسحب — ضربة، 🛡 — حجب",
"✶ Manual: LMB — katana, RMB — block, Shift — blink, Q — shurikens, G — teleport":"‏✶ تحكّم يدوي: زر الفأرة الأيسر — كاتانا، الأيمن — حجب، Shift — اندفاع، Q — شوريكن، G — انتقال آني",
"✶ Ninja: tap an enemy — dash & cut, swipe on the right — slash, ● — strike, 🛡 — block (timed = parry), ⇑ — blink, ✦ — shurikens, ◎ — teleport, AUTO — on her own":"‏✶ النينجا: نقرة على عدو — اندفاع وضربة، سحب على اليمين — ضربة سيف، ● — ضربة، 🛡 — صدّ (بتوقيت دقيق = ردّ)، ⇑ — وميض، ✦ — شوريكن، ◎ — انتقال آني، AUTO — تلقائي",
"✶ Ninja: LMB — katana (hold — heavy cut), RMB — block (timed = parry), Shift/Z — blink, Q — shurikens, G — teleport to the crosshair, jump in the air — double jump / wall-run, {0} — AUTO":"‏✶ النينجا: زر الفأرة الأيسر — كاتانا (اضغط مطوّلاً — ضربة ثقيلة)، زر الفأرة الأيمن — صدّ (بتوقيت دقيق = ردّ)، Shift/Z — وميض، Q — شوريكن، G — انتقال آني إلى المنظار، قفزة في الهواء — قفزة مزدوجة / جري على الجدار، {0} — AUTO",
