"Radio Portal Meteor: 100+ tracks by EDMITRY right in the game — the 📻 button (PC: key 5, [ ] — track). Music streams on demand and does not bloat the game; volume and autostart in Settings, plus a \"Listen on Spotify\" link.":"راديو Portal Meteor: أكثر من 100 مقطوعة لـ EDMITRY داخل اللعبة — زر 📻 (على الحاسوب: المفتاح 5، [ ] — المقطوعة). تُبَثّ الموسيقى عند الطلب دون تثقيل اللعبة؛ مستوى الصوت والتشغيل التلقائي في الإعدادات، مع رابط «استمع على Spotify».",
