"Radio Portal Meteor on/off ([ ] — track, Shift+[ ] — volume)":"تشغيل/إيقاف راديو Portal Meteor ([ ] — المقطوعة، Shift+[ ] — مستوى الصوت)",
"📻 on the right — Radio Portal Meteor: music by EDMITRY while you fight.":"‏📻 على اليمين — راديو Portal Meteor: موسيقى EDMITRY أثناء القتال.",
"{0} — Radio Portal Meteor: music by EDMITRY while you fight. [ ] — track.":"‏{0} — راديو Portal Meteor: موسيقى EDMITRY أثناء القتال. [ ] — المقطوعة.",
"Radio Portal Meteor (EDMITRY): volume":"راديو Portal Meteor (EDMITRY): مستوى الصوت",
"Radio: start by itself in battle":"الراديو: يعمل تلقائياً في القتال",
"Robo-ninja: a cyborg with a katana. Unlocked at the Barracks with the \"Shadow Protocol\" research (needs a Mech Factory). Teleports into enemy zones by herself, cuts enemies apart (no blood — sparks), dashes, shuriken, duels with the enemy ninja. Possess her — AUTO mode or manual control (own buttons on the phone).":"روبو-نينجا: سايبورغ بسيف كاتانا. تُفتح في الثكنة ببحث «بروتوكول الظل» (يتطلب مصنع آليات). تنتقل آنياً إلى مناطق العدو بنفسها، وتقطّع الأعداء (بلا دماء — شرارات)، وتندفع، وترمي الشوريكن، وتنازل نينجا العدو. اشغلها — وضع AUTO أو تحكّم يدوي (على الهاتف — أزرار خاصة).",
"Radio Portal Meteor: 103 EDMITRY tracks right in the game. Key 5 (rebindable), on the phone — ☰ → Settings → Sound. Volume and \"auto-play in battle\" in the settings; the music ducks under explosions and radio voice.":"راديو Portal Meteor: 103 مقطوعة لـ EDMITRY داخل اللعبة. المفتاح 5 (قابل لإعادة التعيين)، وعلى الهاتف — ☰ ← الإعدادات ← الصوت. مستوى الصوت و«التشغيل التلقائي في القتال» في الإعدادات؛ تخفت الموسيقى عند الانفجارات وصوت اللاسلكي.",
"New languages: Uzbek and Tajik — complete; Chinese, Spanish, Portuguese — partial. New language selector in the menu next to \"New match\".":"لغات جديدة: الأوزبكية والطاجيكية — كاملتان؛ الصينية والإسبانية والبرتغالية — جزئية. اختيار لغة جديد في القائمة بجانب «مباراة جديدة».",
"Phone: \"hide icons\" 👁 gathers the remaining buttons into a tidy column at the right edge; portrait no longer overlaps; iPhone — the game no longer fights Safari gestures, and \"Share → Add to Home Screen\" launches it full screen.":"الهاتف: «إخفاء الأيقونات» 👁 يجمع الأزرار المتبقية في عمود مرتّب عند الحافة اليمنى؛ الوضع الطولي لم يعد متداخلاً؛ آيفون — اللعبة لا تتعارض مع إيماءات Safari، و«مشاركة ← إضافة إلى الشاشة الرئيسية» يشغّلها بملء الشاشة.",
"From v7.8.1: ☰ corner menu (pause, restart, training, graphics), no auto-Dendy, ✋ action button on the phone. v7.8.1 and v7.8 stay in the \"🕘 Game version\" menu.":"من v7.8.1: قائمة ☰ في الزاوية (إيقاف مؤقت، إعادة، تدريب، رسومات)، بلا Dendy تلقائي، زر الإجراء ✋ على الهاتف. v7.8.1 وv7.8 باقيتان في قائمة «🕘 إصدار اللعبة».",
