"Strip: ⟳ to rotate, or drag from the target along the run":"الشريط: ⟳ للتدوير، أو اسحب من الهدف باتجاه الاقتراب",
"Strip: mouse wheel or R to rotate, or drag from the target along the run":"الشريط: عجلة الفأرة أو R للتدوير، أو اسحب بالفأرة من الهدف باتجاه الاقتراب",
"Into the tunnel: {0} vehicle(s)":"إلى النفق: {0} آلية",
"Light and medium vehicles go into the nearest open tunnel":"الآليات الخفيفة والمتوسطة تدخل أقرب نفق مفتوح",
"Swarm. Squads within 70 m of the burrow (and selected ones), plus selected light/medium vehicles (Jackal, Hammer, Grad), go through the tunnel. Or: select and RMB/tap the burrow.":"السِّرب. الفرق ضمن 70 م من الجحر (والمحدَّدة) والآليات الخفيفة/المتوسطة المحدَّدة (\"ابن آوى\"، \"المطرقة\"، \"غراد\") تمرّ عبر النفق وتخرج من الطرف الآخر. أو: حدّد ثم زر الفأرة الأيمن/نقرة على الجحر.",
"Air strikes":"الضربات الجوية",
"Carpet bombing and napalm: aiming, rotating the strip, enemy warning, calling from battle":"القصف السجّادي والنابالم: التصويب، تدوير الشريط، تحذير العدو، الاستدعاء أثناء المعركة",
"Terrain and lakes":"التضاريس والبحيرات",
"Lava burns, ice slides, methane explodes from fire, the rock hangar is cover":"الحمم تحرق، والجليد ينزلق، والميثان ينفجر بالنار، وحظيرة الصخور ساتر",
"Swarm: tunnels":"السِّرب: الأنفاق",
"You play the Swarm: tunnel burrow, exit up to 220 m, dust warning, squads and vehicles through":"تلعب بالسِّرب: جحر النفق، مخرج حتى 220 م، تحذير الغبار، الفرق والآليات تمرّ عبره",
"Consortium: fortifications":"الكونسورتيوم: التحصينات",
"You play the Consortium: barrier chains, repair post, field repair by builders":"تلعب بالكونسورتيوم: سلاسل الحواجز، نقطة الإصلاح، الإصلاح الميداني بالمهندسين",
"Bosses":"الزعماء",
"\"Bastion\" and \"Reaper\": from 12:00 (skipped here), plant, assembly, orders, weak spots, possession":"‏\"الحصن\" و\"الحصّاد\": من 12:00 (يُتخطّى هنا)، المصنع، التجميع، الأوامر، نقاط الضعف، التحكّم",
