"MY SQUADS":"فرقي",
"Veterancy carries over between battles. A squad earns XP (infantry 1, building 2, vehicle 3), levels, stars and perks. Veterans deploy first in a new battle. A lost squad loses everything and joins the Fallen.":"الخبرة القتالية تبقى بين المعارك. تجمع الفرقة نقاط خبرة (مشاة 1، مبنى 2، آلية 3)، وتنال مستويات ونجوماً ومزايا. يدخل المحاربون القدامى أولاً في كل معركة جديدة. الفرقة التي تسقط تخسر كل شيء وتنضم إلى الساقطين.",
"Active":"في الخدمة",
"Empty for now — squads get names in your next battle.":"فارغ حالياً — تحصل الفرق على أسمائها في معركتك القادمة.",
"Perks by level":"المزايا حسب المستوى",
