"campaign":"الحملة",
"\"Commander\" mode on phone":"وضع «القائد» على الهاتف",
"Smoke grenades":"قنابل دخانية",
"A screen at a point for 14 s — enemies cannot see through.":"ستار دخان في نقطة لمدة 14 ث — لا يرى الأعداء عبره.",
"Flank sprint":"اندفاع جانبي",
"Run to a point at ×1.6 speed without stopping to fight (7 s).":"اركض إلى نقطة بسرعة ×1.6 دون الانخراط في القتال (7 ث).",
"Suppressing fire":"نيران كثيفة",
"Saturating fire on a 14 m area: enemies slowed and missing (7 s).":"وابل نار على مساحة 14 م: يتباطأ الأعداء ويخطئون الإصابة (7 ث).",
"Field medic":"مسعف ميداني",
"+20% hull to all at once, then 4 s of repair.":"‏+20% متانة للجميع فوراً، ثم إصلاح لمدة 4 ث.",
"Regen burst":"دفعة تجدّد",
"Swarm: 8 s of fast regeneration for the whole squad.":"الحشد: تجدّد سريع للفرقة كلها لمدة 8 ث.",
"Grenade volley":"رشقة قنابل يدوية",
"Every trooper throws a grenade at the point.":"كل جندي يرمي قنبلة يدوية نحو النقطة.",
"AT rocket":"صاروخ مضاد للدروع",
"Heavy rockets at a vehicle or building (up to 3).":"صواريخ ثقيلة على آلية أو مبنى (حتى 3).",
"Mini barrier":"حاجز مصغّر",
