"Living world":"عالم حيّ",
"Your units ask for help and reward you, heroes give quests, a stalled front is broken by an op":"وحداتك تطلب المساعدة وتكافئك، والأبطال يمنحون المهمات، والجبهة المتعثّرة تُكسر بعملية",
"A request":"طلب الرفاق",
"Breakthrough":"نقطة تحوّل",
"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"وحداتك تطلب المساعدة أحياناً: نداء عبر اللاسلكي، وبطاقة «طلب»، وعلامة ✋. فرقة محاصَرة — دمّر الأعداء القريبين منها. المكافأة: جندي بكبسولة من القاعدة، أو مدفع من صندوق المركبة، أو مقعد الرامي، أو تغطية مدارية. لا تريد؟ ✕ أو تجاهل الطلب ببساطة.",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"الكشّاف المحنّك «البومة» يعرض عليك مهمة. Y — قبول (N — رفض). توجّه إلى العلامة ★، أزل الحرس وابقَ قرب الطيار 3 s — سينضم إلى فرقتك.",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"الجبهة متوقفة — المقر يعرض عليك نقطة تحوّل. Y — قبول. احتفظ بالمرحّل 8 s دون أعداء قربك: تنكشف خريطة العدو 60 s. المولّد — تصمت أبراج العدو 2 دقيقة. في وضع الاستراتيجي — «كلّف فرقة». العدو قادر على ذلك أيضاً: راقب ⚠.",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"وحداتك تطلب المساعدة: بطاقة «طلب» وعلامة ✋. دمّر الأعداء قرب الفرقة المحاصَرة — تنل مكافأة. ✕ — تخطَّ.",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"البطل «البومة» يعرض عليك مهمة — انقر «قبول». توجّه إلى ★، أزل الحرس، وابقَ قرب الطيار.",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"الجبهة متوقفة — انقر «قبول» واحتفظ بالمرحّل 8 s: تنكشف خريطة العدو لدقيقة.",
