"2. Play and think aloud: what is unclear, annoying, fun. The corner shows version, time and FPS — they match the recording to the notes.":"‏2. العب وفكّر بصوت عالٍ: ما غير الواضح، وما المزعج، وما الممتع. تعرض زاوية الشاشة الإصدار والوقت وعدد الإطارات — بها يُطابَق التسجيل مع الملاحظات.",
